-- Refresh repeated generic exam prompts with course-specific questions.
-- Apply ONLY to the Galini Training Portal PREVIEW database after approval.
-- Preserves each assessment's existing course-specific questions and replaces
-- cross-course repeated prompts with three questions written for that course.

WITH question_updates(course_title, additions) AS (
 VALUES
 ('ACORD Forms Workshop', '[{"prompt":"Which detail belongs in the ACORD 125 applicant section?","choices":["Legal entity and applicant contact details","Only the agent commission","Only the final premium"],"correct":0},{"prompt":"What should be checked when completing ACORD 126?","choices":["GL operations, classifications and exposure basis","Vehicle lienholder only","Dwelling replacement cost only"],"correct":0},{"prompt":"What is the key quality check for an ACORD 140 property schedule?","choices":["Reconcile each location, occupancy and property value","Use one combined value for every location","Leave protection details blank"],"correct":0}]'::jsonb),
('Commercial Auto and Workers Compensation', '[{"prompt":"Which vehicle detail is essential to confirm for a commercial auto submission?","choices":["VIN and garaging address","Employee payroll frequency","Building roof material"],"correct":0},{"prompt":"How should workers compensation payroll be organized?","choices":["By state and actual job classification","By employee age only","By vehicle type"],"correct":0},{"prompt":"What should be verified before relying on a subcontractor exclusion?","choices":["Subcontractor duties, costs and certificates where required","Only the subcontractor''s business name","Only the agency''s commission"],"correct":0}]'::jsonb),
('Commercial Lines Foundations', '[{"prompt":"Which exposure set is most important before selecting a commercial market?","choices":["Operations, locations, sales, payroll, property and losses","Only the requested premium","Only the business name"],"correct":0},{"prompt":"What should an agent do when payroll or sales figures conflict?","choices":["Confirm the correct basis with the insured and record the source","Choose the lower figure","Average the two figures without asking"],"correct":0},{"prompt":"What belongs in a useful underwriter submission summary?","choices":["Operations, exposures, loss context and open items","Only a request for the lowest price","Only the agency contact"],"correct":0}]'::jsonb),
('Commercial Property Quoting Practice', '[{"prompt":"Which value should be scheduled separately from the building?","choices":["Business personal property and stock","Agent commission","Auto liability limit"],"correct":0},{"prompt":"Which item is a property protection safeguard?","choices":["Automatic sprinkler system","Driver experience","Workers compensation experience mod"],"correct":0},{"prompt":"How should a prior property loss be described?","choices":["Date, cause, amount and completed corrective action","Only the renewal premium","Only the insured''s opinion"],"correct":0}]'::jsonb),
('General Liability Quoting Practice', '[{"prompt":"Which activity can materially change a general liability classification?","choices":["Installation work performed at customer locations","Changing the agency logo","Changing the invoice format"],"correct":0},{"prompt":"Which exposure basis is commonly used for some GL classes?","choices":["Gross sales or payroll, as specified by the carrier","Mortgage balance","Number of policy pages"],"correct":0},{"prompt":"What should be disclosed when subcontractors perform work?","choices":["Their scope, cost and required insurance evidence","Only their first names","Nothing if they are paid by invoice"],"correct":0}]'::jsonb),
('Quote Review and Binding Workflow', '[{"prompt":"Which item must match between the accepted quote and binder?","choices":["Named insured, effective date, limits and coverage terms","Only the agent''s preferred carrier","Only the payment receipt"],"correct":0},{"prompt":"When should a bind request be treated as confirmed coverage?","choices":["Only after authorized carrier or wholesaler confirmation","Immediately when the email is sent","When the client signs a proposal"],"correct":0},{"prompt":"What is a key post-bind quality check?","choices":["Compare the binder and issued policy to the accepted quote","Delete the quote version","Assume all requested endorsements were issued"],"correct":0}]'::jsonb),
('Commercial Auto Underwriting & Rating', '[{"prompt":"What does the covered auto symbol schedule help determine?","choices":["Which categories of autos are covered","Which employees receive payroll","Which buildings are insured"],"correct":0},{"prompt":"Why must radius and vehicle use be confirmed?","choices":["They affect exposure, eligibility and rating","They determine the agency''s commission","They replace driver information"],"correct":0},{"prompt":"When should an MVR be ordered?","choices":["After required authorization and under applicable rules","Without the driver''s knowledge in every case","Only after the first claim"],"correct":0}]'::jsonb),
('Commercial Package & BOP Academy', '[{"prompt":"Which risk is more likely to need a CPP review rather than a standard BOP?","choices":["A complex operation with multiple coverage parts or unusual exposures","A simple eligible office with standard exposures","A personal auto household"],"correct":0},{"prompt":"Which values should be separated by location?","choices":["Building, BPP, stock and business income","Only total annual premium","Only payroll and sales combined"],"correct":0},{"prompt":"Which exposure may need a separate policy outside a basic BOP?","choices":["Commercial auto or workers compensation","Office stationery","Agency software subscription"],"correct":0}]'::jsonb),
('Commercial Umbrella & Excess Liability', '[{"prompt":"What should be reviewed before submitting an umbrella application?","choices":["Underlying GL, auto and employers liability policies and limits","Only the property replacement cost","Only the agency''s E&O limit"],"correct":0},{"prompt":"What does an excess policy attachment point represent?","choices":["The level where the excess layer begins responding, subject to its terms","The annual premium due date","The policy''s mailing address"],"correct":0},{"prompt":"Why is a certificate insufficient for full umbrella review?","choices":["It does not replace review of actual underlying policies and endorsements","It always expands every exclusion","It confirms all claims are covered"],"correct":0}]'::jsonb),
('Homeowners Insurance Academy', '[{"prompt":"What is the best basis for Coverage A?","choices":["A supported estimate of the home''s reconstruction cost","The home''s market value alone","The outstanding mortgage balance"],"correct":0},{"prompt":"Which property feature should be checked for homeowners eligibility?","choices":["Roof age, material and condition","The agent''s years of service","The client''s auto deductible"],"correct":0},{"prompt":"How should flood exposure be explained?","choices":["Standard homeowners coverage commonly excludes flood; discuss separate coverage","Flood is always included automatically","Flood is covered whenever wind is covered"],"correct":0}]'::jsonb),
('Insurance Rating, Quote Comparison & Proposal Skills', '[{"prompt":"What should a training premium estimate clearly disclose?","choices":["Assumptions, inputs and that it is not a carrier quote","A guarantee of the final carrier price","A promise that coverage is bindable"],"correct":0},{"prompt":"Which factors should be held consistent in a quote comparison?","choices":["Limits, deductibles, forms, exposures and effective dates","Only the carrier name","Only the agent''s commission"],"correct":0},{"prompt":"What should be explained when two premiums differ materially?","choices":["Coverage differences, rating assumptions, fees and subjectivities","Only which premium is lower","Only the carrier''s logo"],"correct":0}]'::jsonb),
('Personal Auto Insurance Academy', '[{"prompt":"Which household detail can affect personal auto eligibility?","choices":["All household residents and regular vehicle operators","The insured''s business inventory","The home''s roof material"],"correct":0},{"prompt":"What should be verified for each vehicle?","choices":["VIN, garaging, use, mileage and ownership","Only the vehicle color","Only the monthly loan payment"],"correct":0},{"prompt":"What is important when comparing two personal auto offers?","choices":["Same drivers, vehicles, limits, deductibles and policy term","Different drivers and effective dates","Premium only"],"correct":0}]'::jsonb),
('Personal Lines Rating & Coverage Workshop', '[{"prompt":"What should be reviewed for a condo unit-owner policy?","choices":["Association master policy responsibility and unit improvements","Only the building''s market value","Only the auto liability limit"],"correct":0},{"prompt":"What is essential for a personal umbrella submission?","choices":["Underlying auto and homeowners limits and household exposures","Only the umbrella premium","Only the applicant''s mailing preference"],"correct":0},{"prompt":"Which item may require separate personal lines coverage?","choices":["Flood or scheduled high-value property","Ordinary household furniture in every case","The agent''s office equipment"],"correct":0}]'::jsonb),
('Workers Compensation & Payroll Rating', '[{"prompt":"What is the correct basis for workers compensation class assignment?","choices":["Actual employee duties under applicable state rules","Employee job title alone","The employer''s preferred rate"],"correct":0},{"prompt":"Why are owner/officer elections important?","choices":["They can affect whether owner payroll is included or excluded","They determine property limits","They replace the experience modification"],"correct":0},{"prompt":"What does a workers compensation audit reconcile?","choices":["Estimated payroll and classifications against actual exposure","Vehicle values against building values","Commission against agency fees"],"correct":0}]'::jsonb)
)
UPDATE training_assessments AS a
SET questions =
 COALESCE((
  SELECT jsonb_agg(item.question ORDER BY item.ordinality)
  FROM jsonb_array_elements(a.questions) WITH ORDINALITY AS item(question, ordinality)
  WHERE lower(trim(item.question->>'prompt')) NOT IN ('a submission is missing an important supporting document. what is the correct response?','which is the best way to handle an underwriting question you cannot verify?','a client selects a quote with different limits than the alternative. what should the proposal show?','an application value conflicts with a supporting document. what is the correct action?','what should be reviewed before recommending one quote over another?','a risk has an unusual operation that may affect eligibility. what should the agent do?','when is it appropriate to tell a client coverage is bound?','what makes an account file useful for a future audit or service request?')
 ), '[]'::jsonb) || updates.additions
FROM training_courses AS c
JOIN question_updates AS updates ON updates.course_title = c.title
WHERE a.course_id = c.id
  AND a.is_published = true;
